import struct

CT_STOP=0
CT_TRUE=1
CT_FALSE=2
CT_BYTE=3
CT_I16=4
CT_I32=5
CT_I64=6
CT_DOUBLE=7
CT_BINARY=8
CT_LIST=9
CT_SET=10
CT_MAP=11
CT_STRUCT=12

def read_varint(data, pos):
    res=0; shift=0
    while True:
        b=data[pos]; pos+=1
        res |= (b & 0x7f) << shift
        if b & 0x80 ==0:
            break
        shift+=7
    return res, pos
def zigzag(n): return (n>>1) ^ -(n&1)

class Dec:
    def __init__(self,data):
        self.d=data
        self.p=0
        self.stack=[]
        self.last=0
    def b(self):
        v=self.d[self.p]; self.p+=1; return v
    def varint(self):
        v,self.p=read_varint(self.d,self.p); return v
    def zigzag(self):
        return zigzag(self.varint())
    def field_begin(self):
        b=self.b()
        if b==0:
            return None, CT_STOP
        delta=(b>>4)&0xf
        typ=b&0xf
        if delta==0:
            fid=zigzag(self.varint())
        else:
            fid=self.last+delta
        self.last=fid
        return fid, typ
    def list_begin(self):
        b=self.b()
        sz=(b>>4)&0xf
        typ=b&0xf
        if sz==15:
            sz=self.varint()
        return typ, sz
    def skip(self, typ):
        if typ==CT_TRUE or typ==CT_FALSE:
            pass
        elif typ==CT_BYTE:
            self.p+=1
        elif typ in (CT_I16,CT_I32,CT_I64):
            self.varint()
        elif typ==CT_DOUBLE:
            self.p+=8
        elif typ==CT_BINARY:
            l=self.varint()
            self.p+=l
        elif typ in (CT_LIST,CT_SET):
            t,sz=self.list_begin()
            for _ in range(sz):
                self.skip(t)
        elif typ==CT_MAP:
            sz=self.varint()
            if sz>0:
                b=self.b()
                ktype=(b>>4)&0xf
                vtype=b&0xf
                for _ in range(sz):
                    self.skip(ktype)
                    self.skip(vtype)
        elif typ==CT_STRUCT:
            # need stack for last
            saved=self.last
            self.last=0
            while True:
                fid,ft=self.field_begin()
                if ft==CT_STOP:
                    break
                self.skip(ft)
            self.last=saved
        else:
            raise ValueError(f"skip unknown {typ}")

