CT_TRUE=1
CT_FALSE=2
CT_BYTE=3
CT_I16=4
CT_I32=5
CT_I64=6
CT_DOUBLE=7
CT_BINARY=8
CT_LIST=9
CT_SET=10
CT_MAP=11
