        pos+=1
        n |= (b & 0x7f) << shift
        if b & 0x80 ==0:
            break
        shift+=7
    out=bytearray()
    while pos < len(data):
        b=data[pos]
        pos+=1
        typ=b & 0x03
        if typ==0:
            length=(b>>2)+1
            if length-1>=60:
                extra=(b>>2)-60
                if extra==1:
                    length=data[pos]+1
                    pos+=1
                elif extra==2:
                    length=struct.unpack('<H', data[pos:pos+2])[0]+1
                    pos+=2
                elif extra==3:
                    length=struct.unpack('<I', data[pos:pos+3]+b'\x00')[0]+1
                    pos+=3
                elif extra==4:
                    length=struct.unpack('<I', data[pos:pos+4])[0]+1
                    pos+=4
                else:
                    raise ValueError("invalid literal")
            out.extend(data[pos:pos+length])
            pos+=length
        elif typ==1:
            length=((b>>2)&0x7)+4
            offset=((b & 0xe0)<<3) | data[pos]
            pos+=1
            for i in range(length):
                out.append(out[-offset])
        elif typ==2:
            length=(b>>2)+1
            offset=struct.unpack('<H', data[pos:pos+2])[0]
            pos+=2
            for i in range(length):
                out.append(out[-offset])
        elif typ==3:
            length=(b>>2)+1
            offset=struct.unpack('<I', data[pos:pos+4])[0]
            pos+=4
            for i in range(length):
                out.append(out[-offset])
        else:
            raise ValueError("unknown")
    return bytes(out)

def decompress_page(data, codec, uncompressed_size):
    if codec==0:
        return data
    elif codec==1:
        return snappy_decompress(data)
    elif codec==2:
        import zlib, gzip
        try:
            return zlib.decompress(data, 31)
        except:
            return gzip.decompress(data)
    elif codec==5:
        import ctypes
        lib=ctypes.CDLL("liblz4.so.1")
        lib.LZ4_decompress_safe.argtypes=[ctypes.c_char_p, ctypes.c_char_p, ctypes.c_int, ctypes.c_int]
        lib.LZ4_decompress_safe.restype=ctypes.c_int
        dst=ctypes.create_string_buffer(uncompressed_size)
        ret=lib.LZ4_decompress_safe(data, dst, len(data), uncompressed_size)
        if ret<0:
            raise ValueError("lz4 failed")
        return dst.raw[:ret] if ret!=uncompressed_size else dst.raw
    elif codec==6:
        import ctypes
        lib=ctypes.CDLL("libzstd.so.1")
        lib.ZSTD_decompress.argtypes=[ctypes.c_void_p, ctypes.c_size_t, ctypes.c_void_p, ctypes.c_size_t]
        lib.ZSTD_decompress.restype=ctypes.c_size_t
        lib.ZSTD_isError.argtypes=[ctypes.c_size_t]
        lib.ZSTD_isError.restype=ctypes.c_uint
        dst=ctypes.create_string_buffer(uncompressed_size)
        src=ctypes.create_string_buffer(data, len(data))
        ret=lib.ZSTD_decompress(dst, uncompressed_size, src, len(data))
        if lib.ZSTD_isError(ret):
            raise ValueError("zstd error")
        return dst.raw[:ret]
    elif codec==4:
        import ctypes
        lib=ctypes.CDLL("libbrotlidec.so.1")
        lib.BrotliDecoderDecompress.argtypes=[ctypes.c_size_t, ctypes.c_char_p, ctypes.c_void_p, ctypes.c_char_p]
        lib.BrotliDecoderDecompress.restype=ctypes.c_int
        dst=ctypes.create_string_buffer(uncompressed_size)
        decoded_size=ctypes.c_size_t(uncompressed_size)
        ret=lib.BrotliDecoderDecompress(len(data), data, ctypes.byref(decoded_size), dst)
        if ret!=1:
            raise ValueError("brotli failed")
        return dst.raw[:decoded_size.value]
    else:
        import zlib
        try:
            return zlib.decompress(data)
        except:
            return data

def decode_page_header(dec):
    saved=dec.last
    dec.last=0
    hdr={}
    while True:
        fid, ft=dec.field_begin()
        if ft==CT_STOP:
            break
        if fid==1 and ft==CT_I32:
            hdr['type']=dec.zigzag()
        elif fid==2 and ft==CT_I32:
            hdr['uncompressed_size']=dec.zigzag()
        elif fid==3 and ft==CT_I32:
            hdr['compressed_size']=dec.zigzag()
        elif fid==4 and ft==CT_I32:
            hdr['crc']=dec.zigzag()
        elif fid==5 and ft==CT_STRUCT:
            saved2=dec.last
            dec.last=0
            dph={}
            while True:
                fid2, ft2=dec.field_begin()
                if ft2==CT_STOP:
                    break
                if fid2==1 and ft2==CT_I32:
                    dph['num_values']=dec.zigzag()
                elif fid2==2 and ft2==CT_I32:
                    dph['encoding']=dec.zigzag()
                elif fid2==3 and ft2==CT_I32:
                    dph['definition_level_encoding']=dec.zigzag()
                elif fid2==4 and ft2==CT_I32:
                    dph['repetition_level_encoding']=dec.zigzag()
                elif fid2==5 and ft2==CT_STRUCT:
                    dec.skip(CT_STRUCT)
                else:
                    dec.skip(ft2)
            dec.last=saved2
            hdr['data_page_header']=dph
        elif fid==7 and ft==CT_STRUCT:
            saved2=dec.last
            dec.last=0
            dph={}
            while True:
                fid2, ft2=dec.field_begin()
                if ft2==CT_STOP:
                    break
                if fid2==1 and ft2==CT_I32:
                    dph['num_values']=dec.zigzag()
                elif fid2==2 and ft2==CT_I32:
                    dph['encoding']=dec.zigzag()
                elif fid2==3 and ft2==CT_I32:
                    dph['is_sorted']=dec.zigzag()
                else:
                    dec.skip(ft2)
            dec.last=saved2
            hdr['dictionary_page_header']=dph
        elif fid==8 and ft==CT_STRUCT:
            dec.skip(CT_STRUCT)
        else:
            dec.skip(ft)
    dec.last=saved
    return hdr

def read_varint(data, pos):
    res=0
    shift=0
    while True:
        b=data[pos]
        pos+=1
        res |= (b & 0x7f) << shift
        if b & 0x80 ==0:
            break
        shift+=7
    return res, pos

def decode_levels(data, bit_width, num_values):
    if bit_width==0:
        return [0]*num_values, 0
    out=[]
    pos=0
    while len(out) < num_values and pos < len(data):
        header, pos = read_varint(data, pos)
        is_bit_packed = header & 1
        count = header >> 1
        if is_bit_packed:
            bytes_per_group = (bit_width*8+7)//8
            for _ in range(count):
                if pos+bytes_per_group > len(data):
                    break
                chunk=data[pos:pos+bytes_per_group]
                pos+=bytes_per_group
                buf=0
                bits=0
                p=0
                for _ in range(8):
                    while bits < bit_width:
                        if p >= len(chunk):
                            break
                        buf |= chunk[p] << bits
                        bits+=8
                        p+=1
                    out.append(buf & ((1<<bit_width)-1))
                    buf >>= bit_width
                    bits -= bit_width
                    if len(out) >= num_values:
                        break
        else:
            bytes_per_value=(bit_width+7)//8
            if pos+bytes_per_value > len(data):
                break
            val_bytes=data[pos:pos+bytes_per_value]
            pos+=bytes_per_value
            val=0
            for i in range(bytes_per_value):
                val |= val_bytes[i] << (i*8)
            if bit_width<32:
                val &= (1<<bit_width)-1
            out.extend([val]*count)
    return out[:num_values], pos

def decode_plain_values(data, type_id, num_values, type_length=None):
    res=[]
    pos=0
    if type_id==0:
        for i in range(num_values):
            byte_idx=i//8
            bit_idx=i%8
            if byte_idx < len(data):
                b=data[byte_idx]
                val=(b>>bit_idx)&1
                res.append(bool(val))
            else:
                res.append(False)
        return res
    elif type_id==1:
        for i in range(num_values):
            if pos+4 > len(data):
                break
            v=struct.unpack('<i', data[pos:pos+4])[0]
            pos+=4
            res.append(v)
        return res
    elif type_id==2:
        for i in range(num_values):
            if pos+8 > len(data):
                break
            v=struct.unpack('<q', data[pos:pos+8])[0]
            pos+=8
            res.append(v)
        return res
    elif type_id==3:
        for i in range(num_values):
            if pos+12 > len(data):
                break
            raw=data[pos:pos+12]
            pos+=12
            res.append(raw)
        return res
    elif type_id==4:
        for i in range(num_values):
            if pos+4 > len(data):
                break
            v=struct.unpack('<f', data[pos:pos+4])[0]
            pos+=4
            res.append(v)
        return res
    elif type_id==5:
        for i in range(num_values):
            if pos+8 > len(data):
                break
            v=struct.unpack('<d', data[pos:pos+8])[0]
            pos+=8
            res.append(v)
        return res
    elif type_id==6:
        for i in range(num_values):
            if pos+4 > len(data):
                break
            l=struct.unpack('<i', data[pos:pos+4])[0]
            pos+=4
            if pos+l > len(data):
                break
            raw=data[pos:pos+l]
            pos+=l
            try:
                s=raw.decode('utf-8')
                res.append(s)
            except:
                res.append(raw)
        return res
    elif type_id==7:
        if type_length is None:
            type_length=1
        for i in range(num_values):
            if pos+type_length > len(data):
                break
            raw=data[pos:pos+type_length]
            pos+=type_length
            res.append(raw)
        return res
    else:
        return res

