def format_value(v, type_id=None):
    if v is None:
        return "NULL"
    if isinstance(v, bool):
        return "true" if v else "false"
    if isinstance(v, bytes):
        try:
            s=v.decode('utf-8')
            if all(32 <= ord(c) < 127 for c in s):
                return s
            else:
                return repr(v)
        except:
            return repr(v)
    if isinstance(v, float):
        # Format to avoid scientific notation issues; original shows 0.0, 1.1 etc
        # Use Python's default str
        return ('%f' % v).rstrip('0').rstrip('.') if '.' in ('%f' % v) else str(v)
    if isinstance(v, list):
        inner=", ".join(format_value(x) for x in v)
        return f"[{inner}]"
    if isinstance(v, dict):
        inner=", ".join(f"{k}: {format_value(val)}" for k,val in v.items())
        return "{"+inner+"}"
    return str(v)

def run(path):
    error_msg = None
    file_meta = None
    file_data = None
    try:
        file_meta, file_data = parse_file_meta(path)
    except FileNotFoundError as e:
        error_msg = 'Custom { kind: Other, error: "No such file or directory (os error 2)" }'
    except IsADirectoryError as e:
        error_msg = 'Custom { kind: Other, error: "External: Is a directory (os error 21)" }'
    except ValueError as e:
        msg=str(e)
        if "encrypted" in msg.lower():
            error_msg = 'Custom { kind: Other, error: "Parquet error: Parquet file has an encrypted footer but the encryption feature is disabled" }'
        elif "too small" in msg.lower():
            error_msg = f'Custom {{ kind: Other, error: "{msg}" }}'
        elif "page header" in msg.lower():
            error_msg = f'Custom {{ kind: Other, error: "parquet: File out of specification: The page header reported the wrong page size" }}'
        elif "unexpected parquet type" in msg:
            error_msg = f'Custom {{ kind: Other, error: "Parquet error: {msg}" }}'
        elif "PAR1" in msg:
            error_msg = f'Custom {{ kind: Other, error: "{msg}" }}'
        else:
            error_msg = f'Custom {{ kind: Other, error: "{msg}" }}'
    except OSError as e:
        if e.errno == 2:
            error_msg = 'Custom { kind: Other, error: "No such file or directory (os error 2)" }'
        elif e.errno == 21:
            error_msg = 'Custom { kind: Other, error: "External: Is a directory (os error 21)" }'
        else:
            error_msg = f'Custom {{ kind: Other, error: "{e}" }}'
    except Exception as e:
        msg=str(e)
        if "unexpected parquet type" in msg:
            error_msg = f'Custom {{ kind: Other, error: "Parquet error: {msg}" }}'
        elif "Number" in msg:
            error_msg = f'Custom {{ kind: Other, error: "parquet: File out of specification: Number {msg.split("Number")[-1]}" }}'
        else:
            error_msg = f'Custom {{ kind: Other, error: "{msg}" }}'

    curses.wrapper(lambda stdscr: _main_loop(stdscr, path, file_meta, file_data, error_msg))

